filldraw(shift(sqrt(3),0)*hex, darkcolor,black);
filldraw(shift(sqrt(3)*2,0)*hex, darkcolor,black);
filldraw(shift(sqrt(3)*2.5,1.5)*hex, darkcolor,black);
